package com.example.sirh.service;

import com.example.sirh.controller.TimeTrackingController.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.*;
import java.util.*;

@Service
public class TimeTrackingService {
    private final JdbcTemplate jdbc;
    private final EmployeeAccessService access;
    private final EmployeeGdprAuditService audit;
    private final ZoneId zone;
    public TimeTrackingService(JdbcTemplate jdbc,EmployeeAccessService access,EmployeeGdprAuditService audit,
                               @org.springframework.beans.factory.annotation.Value("${sirh.time-tracking.zone-id:Europe/Paris}") String zoneId) {
        this.jdbc=jdbc; this.access=access; this.audit=audit; this.zone=ZoneId.of(zoneId);
    }

    public Map<String,Object> today(Authentication actor) {
        int id=selfId(actor); LocalDate date=LocalDate.now(zone);
        List<Map<String,Object>> events=jdbc.queryForList("SELECT id,event_type,event_timestamp,is_regularized FROM time_clock_events WHERE employee_id=? AND (event_timestamp AT TIME ZONE ?)::date=? ORDER BY event_timestamp,id",id,zone.getId(),date);
        int worked=workedMinutes(events,OffsetDateTime.now(zone));
        String next=nextAction(events);
        return Map.of("employeeId",id,"date",date,"serverNow",OffsetDateTime.now(zone),"events",events,"workedMinutes",worked,"nextAction",next);
    }
    @Transactional public Map<String,Object> record(String raw,UUID key,Authentication actor) {
        int id=selfId(actor); jdbc.queryForObject("SELECT id FROM employees WHERE id=? FOR UPDATE",Integer.class,id); String type=normalize(raw);
        var old=jdbc.query("SELECT id,event_type,event_timestamp,is_regularized FROM time_clock_events WHERE employee_id=? AND idempotency_key=?",(rs,n)->event(rs.getLong(1),rs.getString(2),rs.getObject(3,OffsetDateTime.class),rs.getBoolean(4)),id,key);
        if(!old.isEmpty()) return old.getFirst();
        List<Map<String,Object>> events=jdbc.queryForList("SELECT id,event_type,event_timestamp FROM time_clock_events WHERE employee_id=? AND (event_timestamp AT TIME ZONE ?)::date=? ORDER BY event_timestamp,id",id,zone.getId(),LocalDate.now(zone));
        validateTransition(events,type);
        Map<String,Object> created=jdbc.queryForMap("INSERT INTO time_clock_events(employee_id,event_type,event_timestamp,recorded_at,idempotency_key) VALUES (?, ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, ?) RETURNING id,event_type,event_timestamp,is_regularized",id,type,key);
        recalculate(id,LocalDate.now(zone)); audit.record(actor,id,"CREATE","TIME_CLOCK_EVENT"); return created;
    }
    public List<Map<String,Object>> sheets(LocalDate from,LocalDate to,Integer employeeId,Authentication actor) {
        if(from.isAfter(to)||Duration.between(from.atStartOfDay(),to.plusDays(1).atStartOfDay()).toDays()>93) throw new IllegalArgumentException("Période invalide (maximum 93 jours).");
        requireReader(actor); List<Object> args=new ArrayList<>(List.of(from,to)); String sql="""
          SELECT e.id employee_id,e.first_name,e.last_name,e.department_id,s.work_date,s.effective_worked_minutes,
                 s.pause_minutes,s.overtime_25_minutes,s.overtime_50_minutes,s.has_anomaly,s.anomaly_type,s.anomaly_codes,s.status
          FROM daily_time_sheets s JOIN employees e ON e.id=s.employee_id WHERE s.work_date BETWEEN ? AND ?
          """;
        if(employeeId!=null){ensureEmployeeAccess(employeeId,actor);sql+=" AND e.id=?";args.add(employeeId);}
        else if(access.isManager(actor)){List<String> deps=access.managedDepartments(actor); if(deps.isEmpty())return List.of(); sql+=" AND e.department_id IN ("+String.join(",",Collections.nCopies(deps.size(),"?"))+")";args.addAll(deps);}
        sql+=" ORDER BY s.work_date DESC,e.last_name,e.first_name"; return jdbc.queryForList(sql,args.toArray());
    }
    public List<Map<String,Object>> schedule(int employeeId,Authentication actor){ensureEmployeeAccess(employeeId,actor);return jdbc.queryForList("SELECT iso_weekday,start_time,end_time,remote,on_call FROM employee_work_schedules WHERE employee_id=? ORDER BY iso_weekday",employeeId);}
    @Transactional public List<Map<String,Object>> setSchedule(int employeeId,ScheduleRequest request,Authentication actor){access.requireHr(actor);employeeExists(employeeId);Set<Integer> weekdays=new HashSet<>();for(var d:request.days()){if(d.isoWeekday()<1||d.isoWeekday()>7||!d.endTime().isAfter(d.startTime())||!weekdays.add(d.isoWeekday()))throw new IllegalArgumentException("Planning hebdomadaire invalide.");}jdbc.update("DELETE FROM employee_work_schedules WHERE employee_id=?",employeeId);for(var d:request.days())jdbc.update("INSERT INTO employee_work_schedules(employee_id,iso_weekday,start_time,end_time,remote,on_call,updated_by) VALUES (?,?,?,?,?,?,?)",employeeId,d.isoWeekday(),d.startTime(),d.endTime(),Boolean.TRUE.equals(d.remote()),Boolean.TRUE.equals(d.onCall()),actor.getName());return schedule(employeeId,actor);}
    @Transactional public Map<String,Object> requestRegularization(RegularizationRequest request,Authentication actor){int id=selfId(actor);String type=normalize(request.eventType());OffsetDateTime at=request.requestedAt();if(at.isAfter(OffsetDateTime.now(zone)))throw new IllegalArgumentException("Un pointage ne peut pas être demandé dans le futur.");if(request.reason().trim().length()<5||request.reason().length()>500)throw new IllegalArgumentException("Le motif doit contenir entre 5 et 500 caractères.");return jdbc.queryForMap("INSERT INTO time_regularization_requests(employee_id,requested_by,event_type,requested_at,reason) VALUES(?,?,?,?,?) RETURNING *",id,actor.getName(),type,at,request.reason().trim());}
    public List<Map<String,Object>> regularizations(Authentication actor){requireReader(actor);String sql="SELECT r.*,e.first_name,e.last_name,e.department_id FROM time_regularization_requests r JOIN employees e ON e.id=r.employee_id WHERE r.status='en_attente'";if(access.isManager(actor)){List<String>d=access.managedDepartments(actor);if(d.isEmpty())return List.of();sql+=" AND e.department_id IN ("+String.join(",",Collections.nCopies(d.size(),"?"))+") ORDER BY r.created_at";return jdbc.queryForList(sql,d.toArray());}return jdbc.queryForList(sql+" ORDER BY r.created_at");}
    @Transactional public Map<String,Object> review(long requestId,ReviewRequest decision,Authentication actor){if(!access.isHr(actor)&&!access.isManager(actor))throw new ForbiddenOperationException("Validation réservée au manager ou RH.");var row=jdbc.query("SELECT employee_id,event_type,requested_at,reason,status FROM time_regularization_requests WHERE id=?",(rs,n)->new Object[]{rs.getInt(1),rs.getString(2),rs.getObject(3,OffsetDateTime.class),rs.getString(4),rs.getString(5)},requestId).stream().findFirst().orElseThrow(()->new ResourceNotFoundException("Demande introuvable."));int employee=(int)row[0];ensureEmployeeAccess(employee,actor);jdbc.queryForObject("SELECT id FROM employees WHERE id=? FOR UPDATE",Integer.class,employee);if(!"en_attente".equals(row[4]))throw new WorkflowConflictException("Cette demande a déjà été traitée.");if(Boolean.TRUE.equals(decision.approved())){List<Map<String,Object>>day=jdbc.queryForList("SELECT id,event_type,event_timestamp FROM time_clock_events WHERE employee_id=? AND (event_timestamp AT TIME ZONE ?)::date=? ORDER BY event_timestamp,id",employee,zone.getId(),((OffsetDateTime)row[2]).atZoneSameInstant(zone).toLocalDate());validateTransition(day,(String)row[1]);jdbc.update("INSERT INTO time_clock_events(employee_id,event_type,event_timestamp,recorded_at,is_regularized,regularization_reason) VALUES(?,?,?,CURRENT_TIMESTAMP,TRUE,?)",employee,row[1],row[2],row[3]);recalculate(employee,((OffsetDateTime)row[2]).atZoneSameInstant(zone).toLocalDate());}return jdbc.queryForMap("UPDATE time_regularization_requests SET status=?,reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP,decision_note=? WHERE id=? RETURNING *",Boolean.TRUE.equals(decision.approved())?"approuvee":"refusee",actor.getName(),decision.note(),requestId);}
    public Map<String,Object> preference(LocalDate week,Authentication actor){int id=selfId(actor);LocalDate monday=week.with(DayOfWeek.MONDAY);return jdbc.query("SELECT employee_id,week_start,preference FROM time_overtime_preferences WHERE employee_id=? AND week_start=?",(rs,n)->Map.<String,Object>of("employeeId",rs.getInt(1),"weekStart",rs.getDate(2).toLocalDate(),"preference",rs.getString(3)),id,monday).stream().findFirst().orElse(Map.of("employeeId",id,"weekStart",monday,"preference","PAIEMENT"));}
    @Transactional public Map<String,Object> setPreference(PreferenceRequest p,Authentication actor){int id=selfId(actor);String value=p.preference().toUpperCase(Locale.ROOT);if(!Set.of("PAIEMENT","CET").contains(value))throw new IllegalArgumentException("Choix attendu : PAIEMENT ou CET.");LocalDate monday=p.weekStart().with(DayOfWeek.MONDAY);jdbc.update("INSERT INTO time_overtime_preferences(employee_id,week_start,preference) VALUES(?,?,?) ON CONFLICT(employee_id,week_start) DO UPDATE SET preference=EXCLUDED.preference,updated_at=CURRENT_TIMESTAMP",id,monday,value);return preference(monday,actor);}

    private void recalculate(int employee,LocalDate date){List<Map<String,Object>> events=jdbc.queryForList("SELECT event_type,event_timestamp FROM time_clock_events WHERE employee_id=? AND (event_timestamp AT TIME ZONE ?)::date=? ORDER BY event_timestamp,id",employee,zone.getId(),date);List<OffsetDateTime> times=new ArrayList<>();for(var e:events){Object t=e.get("event_timestamp");times.add(t instanceof OffsetDateTime o?o:((java.sql.Timestamp)t).toInstant().atZone(zone).toOffsetDateTime());}int worked=workedMinutes(events,OffsetDateTime.now(zone));int pause=0;for(int i=0;i+1<events.size();i++)if("BREAK".equals(events.get(i).get("event_type"))&&"RESUME".equals(events.get(i+1).get("event_type")))pause+=(int)Duration.between(times.get(i),times.get(i+1)).toMinutes();String first=times.isEmpty()?null:times.getFirst().toString();String last=events.stream().anyMatch(e->"OUT".equals(e.get("event_type")))?times.getLast().toString():null;List<String> anomalies=new ArrayList<>();if(last==null&&!times.isEmpty()&&!date.equals(LocalDate.now(zone)))anomalies.add("SORTIE_MANQUANTE");if(!times.isEmpty()&&last!=null&&Duration.between(times.getFirst(),times.getLast()).toMinutes()>600)anomalies.add("AMPLITUDE_SUPERIEURE_10H");var plannedStart=plannedStart(employee,date);if(!times.isEmpty()&&plannedStart!=null&&times.getFirst().isAfter(plannedStart.plusMinutes(15)))anomalies.add("RETARD_SUPERIEUR_15MIN");LocalDate prev=date.minusDays(1);var prevOut=jdbc.query("SELECT event_timestamp FROM time_clock_events WHERE employee_id=? AND event_type='OUT' AND (event_timestamp AT TIME ZONE ?)::date=? ORDER BY event_timestamp DESC LIMIT 1",(rs,n)->rs.getObject(1,OffsetDateTime.class),employee,zone.getId(),prev);if(!prevOut.isEmpty()&&!times.isEmpty()&&Duration.between(prevOut.getFirst(),times.getFirst()).toHours()<11)anomalies.add("REPOS_QUOTIDIEN_INSUFFISANT");
        int weekly=jdbc.queryForObject("SELECT COALESCE(sum(effective_worked_minutes),0) FROM daily_time_sheets WHERE employee_id=? AND work_date BETWEEN ? AND ? AND work_date<>?",Integer.class,employee,date.with(DayOfWeek.MONDAY),date.with(DayOfWeek.MONDAY).plusDays(6),date);var regime=jdbc.query("SELECT work_regime FROM employee_contracts WHERE employee_id=? AND (end_date IS NULL OR end_date>=?) ORDER BY start_date DESC LIMIT 1",(rs,n)->rs.getString(1),employee,date);int threshold="FORFAIT_JOURS_218".equals(regime.isEmpty()?null:regime.getFirst())?Integer.MAX_VALUE:2100;int excess=Math.max(0,weekly+worked-threshold);int prevExcess=Math.max(0,weekly-threshold);int ot25=Math.min(480,Math.max(0,excess-prevExcess));int ot50=Math.max(0,excess-prevExcess-480);int regular=Math.max(0,worked-ot25-ot50);
        jdbc.update("INSERT INTO daily_time_sheets(employee_id,work_date,effective_worked_minutes,overtime_minutes,has_anomaly,anomaly_type,status,pause_minutes,overtime_25_minutes,overtime_50_minutes,regular_work_minutes,first_in,last_out,anomaly_codes,updated_at) VALUES(?,?,?,?,?,?, 'soumis',?,?,?,?,?::timestamptz,?::timestamptz,?,CURRENT_TIMESTAMP) ON CONFLICT(employee_id,work_date) DO UPDATE SET effective_worked_minutes=EXCLUDED.effective_worked_minutes,overtime_minutes=EXCLUDED.overtime_minutes,has_anomaly=EXCLUDED.has_anomaly,anomaly_type=EXCLUDED.anomaly_type,pause_minutes=EXCLUDED.pause_minutes,overtime_25_minutes=EXCLUDED.overtime_25_minutes,overtime_50_minutes=EXCLUDED.overtime_50_minutes,regular_work_minutes=EXCLUDED.regular_work_minutes,first_in=EXCLUDED.first_in,last_out=EXCLUDED.last_out,anomaly_codes=EXCLUDED.anomaly_codes,updated_at=CURRENT_TIMESTAMP",employee,date,worked,ot25+ot50,!anomalies.isEmpty(),String.join(",",anomalies),pause,ot25,ot50,regular,first,last,anomalies.toArray(String[]::new));}
    private OffsetDateTime plannedStart(int employee,LocalDate date){var r=jdbc.query("SELECT start_time FROM employee_work_schedules WHERE employee_id=? AND iso_weekday=?",(rs,n)->rs.getObject(1,LocalTime.class),employee,date.getDayOfWeek().getValue());return r.isEmpty()?null:date.atTime(r.getFirst()).atZone(zone).toOffsetDateTime();}
    private int workedMinutes(List<Map<String,Object>> e,OffsetDateTime now){int sum=0;OffsetDateTime start=null;boolean paused=false;for(var row:e){String t=String.valueOf(row.get("event_type"));Object raw=row.get("event_timestamp");OffsetDateTime at=raw instanceof OffsetDateTime o?o:raw instanceof java.sql.Timestamp ts?ts.toInstant().atZone(zone).toOffsetDateTime():null;if(at==null)continue;if("IN".equals(t)||"RESUME".equals(t)){start=at;paused=false;}else if("BREAK".equals(t)&&start!=null){sum+=(int)Duration.between(start,at).toMinutes();start=null;paused=true;}else if("OUT".equals(t)&&start!=null){sum+=(int)Duration.between(start,at).toMinutes();start=null;paused=false;}}if(start!=null&&!paused)sum+=(int)Duration.between(start,now).toMinutes();return Math.max(0,sum);}
    private String nextAction(List<Map<String,Object>> events){if(events.isEmpty())return "IN";String last=String.valueOf(events.getLast().get("event_type"));return switch(last){case "IN","RESUME"->"BREAK";case "BREAK"->"RESUME";default->"TERMINE";};}
    private void validateTransition(List<Map<String,Object>> events,String next){if(!Set.of("IN","BREAK","RESUME","OUT").contains(next))throw new IllegalArgumentException("Type de pointage invalide.");String expected=events.isEmpty()?"IN":switch(String.valueOf(events.getLast().get("event_type"))){case "IN","RESUME"->"BREAK";case "BREAK"->"RESUME";default->"TERMINE";};if(!expected.equals(next))throw new WorkflowConflictException("Action attendue : "+expected+".");}
    private String normalize(String value){String v=value.toUpperCase(Locale.ROOT);if("PAUSE".equals(v))return "BREAK";if("REPRISE".equals(v))return "RESUME";if(!Set.of("IN","BREAK","RESUME","OUT").contains(v))throw new IllegalArgumentException("Type de pointage invalide.");return v;}
    private int selfId(Authentication a){if(a==null||!access.isEmployee(a))throw new ForbiddenOperationException("Action réservée au compte salarié.");return jdbc.query("SELECT id FROM employees WHERE user_id=? AND status='actif'",(rs,n)->rs.getInt(1),a.getName()).stream().findFirst().orElseThrow(()->new ForbiddenOperationException("Aucun dossier salarié actif n’est lié à ce compte."));}
    private void employeeExists(int id){if(jdbc.queryForObject("SELECT count(*) FROM employees WHERE id=? AND status='actif'",Integer.class,id)==0)throw new ResourceNotFoundException("Salarié actif introuvable.");}
    private void ensureEmployeeAccess(int id,Authentication actor){employeeExists(id);if(access.isHr(actor))return;if(access.isEmployee(actor)&&selfId(actor)==id)return;if(access.isManager(actor)){String d=jdbc.queryForObject("SELECT department_id FROM employees WHERE id=?",String.class,id);access.requireDepartmentScope(actor,d);return;}throw new ForbiddenOperationException("Accès aux temps non autorisé.");}
    private void requireReader(Authentication a){if(!access.isHr(a)&&!access.isManager(a)&&!access.isEmployee(a))throw new ForbiddenOperationException("Accès aux temps non autorisé.");}
    private Map<String,Object> event(long id,String type,OffsetDateTime at,boolean reg){return Map.of("id",id,"eventType",type,"eventTimestamp",at,"isRegularized",reg);}
}
